  isRoomMinimized: boolean;
  setIsRoomMinimized: (v: boolean) => void;
  setActiveVoiceRoom: (v: Room | null) => void;
  isMicOn: boolean;
  setIsMicOn: (v: boolean) => void;
  showToast: (msg: string) => void;
  contacts: Contact[];
  initialChats: ChatMessage[];
  onUpdateRoom: (updatedRoom: Room) => void;
  onShareToFeed: (room: Room, comment: string) => void;
}

const VoiceRoomOverlay: React.FC<VoiceRoomOverlayProps> = ({
  activeVoiceRoom, isRoomMinimized, setIsRoomMinimized, setActiveVoiceRoom,
  isMicOn, setIsMicOn, showToast, contacts, initialChats, onUpdateRoom, onShareToFeed
}) => {
    // ... (State declarations remain the same)
    const [chatInput, setChatInput] = useState("");
    const [showMenu, setShowMenu] = useState(false);
    const [showGiftPanel, setShowGiftPanel] = useState(false);
    const [showRoomInfo, setShowRoomInfo] = useState(false);
    const [showThemeSwitcher, setShowThemeSwitcher] = useState(false);
    const [showResponsePanel, setShowResponsePanel] = useState(false);

    // Password Setting Modal State
    const [showPasswordSettings, setShowPasswordSettings] = useState(false);
    const [passwordInput, setPasswordInput] = useState("");

    // Gift Animation State
    const [activeGiftEffects, setActiveGiftEffects] = useState<GiftEffect[]>([]);

    // Share State
    const [showShareModal, setShowShareModal] = useState(false);
    const [shareComment, setShareComment] = useState("");

    // Guide State
    const [showGuide, setShowGuide] = useState(false);

    // Feature States
    const [showPlaylist, setShowPlaylist] = useState(false);
    const [showInvite, setShowInvite] = useState(false);
    const [isPlaying, setIsPlaying] = useState(true);
    const [currentSong, setCurrentSong] = useState(PRAISE_SONGS[0]);

    // Bible Reader State
    const [currentBibleChapter, setCurrentBibleChapter] = useState(INITIAL_BIBLE_DATA[0]);
    const [showBibleSelector, setShowBibleSelector] = useState(false);
    const [bibleViewMode, setBibleViewMode] = useState(true); 
    const [bibleSelectionStep, setBibleSelectionStep] = useState<'books' | 'chapters'>('books');
    const [selectedBook, setSelectedBook] = useState<{name: string, chapters: number} | null>(null);
    const [bibleTab, setBibleTab] = useState<'OT' | 'NT'>('OT');
    const [isFetchingScripture, setIsFetchingScripture] = useState(false);

    // Preaching Room State
    const [sermonNotes, setSermonNotes] = useState("在此处输入讲道大纲...\n1. 引言\n2. 经文释义\n3. 生活应用\n4. 呼召与祷告");
    const [isRecordingSermon, setIsRecordingSermon] = useState(false);
    const [showShareRecordingModal, setShowShareRecordingModal] = useState(false);

    // Prayer Wall State
    const [prayerWallContent, setPrayerWallContent] = useState("1. 为世界和平祷告\n2. 为教会复兴祷告\n3. 为身心灵软弱的肢体代祷\n4. 求主赐下智慧与启示的灵");
    const [isEditingPrayerWall, setIsEditingPrayerWall] = useState(false);

    // Management State
    const [selectedParticipant, setSelectedParticipant] = useState<Participant | null>(null);
    const [showUserManageModal, setShowUserManageModal] = useState(false);

    // Edit Description State (New)
    const [isEditingDesc, setIsEditingDesc] = useState(false);
    const [tempDesc, setTempDesc] = useState("");

    const [roomChats, setRoomChats] = useState<ChatMessage[]>(initialChats);

    // --- Gemini Live Integration State ---
    const [isAiConnected, setIsAiConnected] = useState(false);
    const [isAiSpeaking, setIsAiSpeaking] = useState(false);
    const [isAiLoading, setIsAiLoading] = useState(false);

    // Local Participants State
    const [participants, setParticipants] = useState<Participant[]>([
        { id: 'pastor', name: '李牧师 (AI)', avatar: 'https://picsum.photos/100/100?random=p', isSpeaking: false, role: 'host' },
        { id: 'me', name: '我', avatar: 'https://picsum.photos/200/200?random=me', isSpeaking: false, role: 'host' },
        { id: 'u1', name: '张大卫', avatar: 'https://picsum.photos/100/100?random=u1', isSpeaking: false, role: 'speaker' },
        { id: 'u2', name: 'Hannah', avatar: 'https://picsum.photos/100/100?random=u2', isSpeaking: false, role: 'listener' },
        { id: 'u3', name: 'Grace', avatar: 'https://picsum.photos/100/100?random=u3', isSpeaking: false, role: 'listener' },
        { id: 'u4', name: 'Simon', avatar: 'https://picsum.photos/100/100?random=u4', isSpeaking: false, role: 'listener' },
    ]);

    const me = participants.find(p => p.id === 'me');
    const isOnStage = me?.role !== 'listener';
    const canManage = me?.role === 'host' || me?.role === 'admin'; 
    const isHost = me?.role === 'host';

    // Updated reactions state to support optional text
    const [reactions, setReactions] = useState<{id: number, emoji: string, text?: string, left: number}[]>([]);
    const chatContainerRef = useRef<HTMLDivElement>(null);

    // Dynamic Theme determination
    const currentType = activeVoiceRoom.type;
    const isPrayerRoom = currentType === 'prayer';
    const isPraiseRoom = currentType === 'praise';
    const isBibleRoom = currentType === 'bible';
    const isPreachingRoom = currentType === 'preaching';

    // Dynamic Gradient based on Theme
    const getBgGradient = () => {
       switch(currentType) {
          case 'prayer': return 'bg-gradient-to-b from-rose-950 via-slate-900 to-black';
          case 'praise': return 'bg-gradient-to-b from-amber-950 via-slate-900 to-black';
          case 'bible': return 'bg-gradient-to-b from-blue-950 via-slate-900 to-black';
          case 'fellowship': return 'bg-gradient-to-b from-emerald-950 via-slate-900 to-black';
          case 'preaching': return 'bg-gradient-to-b from-purple-950 via-slate-900 to-black';
          default: return 'bg-gradient-to-b from-slate-900 via-blue-950 to-black';
       }
    };
    const bgGradient = getBgGradient();

    // ... (Gemini connection logic remains same)
    const audioContextRef = useRef<AudioContext | null>(null);
    const inputAudioContextRef = useRef<AudioContext | null>(null);
    const aiClientRef = useRef<GoogleGenAI | null>(null);
    const nextStartTimeRef = useRef<number>(0);
    const sessionRef = useRef<any>(null);
    const micStreamRef = useRef<MediaStream | null>(null);
    const processorRef = useRef<ScriptProcessorNode | null>(null);

    // ... (useEffect hooks remain same)
    useEffect(() => {
      setParticipants(prev => prev.map(p => {
        if (p.id === 'pastor') return { ...p, isSpeaking: isAiSpeaking };
        if (p.id === 'me') return { ...p, isSpeaking: isMicOn };
        return p;
      }));
    }, [isAiSpeaking, isMicOn]);

    useEffect(() => {
      const isHidden = localStorage.getItem(`amas_hide_guide_${currentType}`);
      if (!isHidden) {
        setShowGuide(true);
      }
      return () => {
        disconnectFromGemini();
      };
    }, [currentType]);

    const connectToGemini = async () => {
      try {
        setIsAiLoading(true);
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        aiClientRef.current = ai;

        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        audioContextRef.current = new AudioContextClass({ sampleRate: SAMPLE_RATE });
        inputAudioContextRef.current = new AudioContextClass({ sampleRate: 16000 });

        const stream = await navigator.mediaDevices.getUserMedia({ audio: { channelCount: 1, sampleRate: 16000 }});
        micStreamRef.current = stream;

        const sessionPromise = ai.live.connect({
          model: 'gemini-2.5-flash-native-audio-preview-09-2025',
          callbacks: {
            onopen: () => {
              setIsAiConnected(true);
              setIsAiLoading(false);
              showToast("已连接到语音牧师");

              const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
              const processor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
              processorRef.current = processor;

              processor.onaudioprocess = (e) => {
                if (!isMicOn) return; 
                const inputData = e.inputBuffer.getChannelData(0);
                const pcmData = floatTo16BitPCM(inputData);
                const base64Data = arrayBufferToBase64(pcmData.buffer);
                sessionPromise.then(session => {
                   session.sendRealtimeInput({ media: { mimeType: "audio/pcm", data: base64Data } });
                });
              };
              source.connect(processor);
              processor.connect(inputAudioContextRef.current!.destination);
            },
            onmessage: async (message: LiveServerMessage) => {
               const audioData = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
               if (audioData) {
                  setIsAiSpeaking(true);
                  const ctx = audioContextRef.current!;
                  const audioBytes = base64ToUint8Array(audioData);
                  const audioBuffer = ctx.createBuffer(1, audioBytes.length / 2, SAMPLE_RATE);
                  const channelData = audioBuffer.getChannelData(0);
                  const view = new DataView(audioBytes.buffer);
                  for(let i=0; i < audioBytes.length / 2; i++){
                      const pcm16 = view.getInt16(i * 2, true);
                      channelData[i] = pcm16 / 32768.0;
                  }
                  const source = ctx.createBufferSource();
                  source.buffer = audioBuffer;
                  source.connect(ctx.destination);
                  const now = ctx.currentTime;
                  const start = Math.max(now, nextStartTimeRef.current);
                  source.start(start);
                  nextStartTimeRef.current = start + audioBuffer.duration;
                  source.onended = () => {
                     if (ctx.currentTime >= nextStartTimeRef.current - 0.1) setIsAiSpeaking(false);
                  };
               }
               if (message.serverContent?.turnComplete) setIsAiSpeaking(false);
            },
            onclose: () => { setIsAiConnected(false); setIsAiSpeaking(false); },
            onerror: (e) => { setIsAiConnected(false); setIsAiLoading(false); setIsAiSpeaking(false); }
          },
          config: {
            responseModalities: [Modality.AUDIO],
            systemInstruction: "You are Pastor Li, a wise and caring pastor. Listen to students, offer biblical encouragement, and pray for them. Use Chinese language.",
            speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Puck' } } }
          }
        });
        sessionRef.current = sessionPromise;

      } catch (error) {
        setIsAiLoading(false);
        showToast("连接失败，请重试");
      }
    };

    const disconnectFromGemini = () => {
       if (micStreamRef.current) micStreamRef.current.getTracks().forEach(t => t.stop());
       if (processorRef.current) processorRef.current.disconnect();
       if (audioContextRef.current?.state !== 'closed') audioContextRef.current?.close();
       if (inputAudioContextRef.current?.state !== 'closed') inputAudioContextRef.current?.close();
       setIsAiConnected(false);
       setIsAiSpeaking(false);
    };

    // Auto scroll chat
    useEffect(() => {
      if (chatContainerRef.current) {
        chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
      }
    }, [roomChats]);

    const handleSendChat = () => {
      if (!chatInput.trim()) return;
      setRoomChats([...roomChats, { id: `m-${Date.now()}`, user: '我', userAvatar: 'https://picsum.photos/200/200?random=me', text: chatInput, type: 'text' }]);
      setChatInput("");
    };

    const handleQuickResponse = (item: {text: string, icon: string}) => {
      setRoomChats(prev => [...prev, { 
        id: `m-${Date.now()}`, 
        user: '我', 
        userAvatar: me?.avatar, 
        text: `${item.text} ${item.icon}`, 
        type: 'text' 
      }]);
      // Trigger with text for Prayer room context, or just icon
      triggerReaction(item.icon, item.text);
      setShowResponsePanel(false);
    };

    const handleRaiseHand = () => {
        showToast('已举手申请发言...');
        setTimeout(() => {
            setParticipants(prev => prev.map(p => p.id === 'me' ? { ...p, role: 'speaker' } : p));
            setRoomChats(prev => [...prev, { id: `sys-${Date.now()}`, user: '系统', text: '我 上麦了', type: 'system' }]);
            showToast('主持人邀请您上麦');
            setIsMicOn(true);
        }, 1000);
    };

    const handleLeaveStage = () => {
        setParticipants(prev => prev.map(p => p.id === 'me' ? { ...p, role: 'listener', isSpeaking: false } : p));
        setRoomChats(prev => [...prev, { id: `sys-${Date.now()}`, user: '系统', text: '我 下麦了', type: 'system' }]);
        setIsMicOn(false);
        showToast('已下麦');
    };

    const toggleMic = () => {
        if (!isOnStage) return;
        const myData = participants.find(p => p.id === 'me');
        if (myData?.isMutedByHost) {
            showToast('您已被主持人禁言');
            return;
        }
        setIsMicOn(!isMicOn);
    };

    // Removed handleShareContent function

    const triggerReaction = (emoji: string = '❤️', text?: string) => {
      // Use Math.random() to ensure uniqueness even if triggered rapidly
      const newReaction = { id: Date.now() + Math.random(), emoji: emoji, text, left: Math.random() * 60 + 20 };
      setReactions(prev => [...prev, newReaction]);
      setTimeout(() => {
         setReactions(prev => prev.filter(r => r.id !== newReaction.id));
      }, 3500);
    };

    // ... (Gift Logic, Theme Switch, Recording, Edit Desc, Scripture Selection, User Management logic remain same)
    const triggerGiftAnimation = (gift: any) => {
      const id = Date.now();
      const count = gift.cost >= 50 ? 15 : (gift.cost >= 20 ? 5 : 1);

      const newEffects: GiftEffect[] = Array.from({ length: count }).map((_, i) => ({
        id: id + i,
        icon: gift.icon,
        type: gift.effect,
        color: gift.theme,
        x: Math.random() * 60 + 20,
        y: Math.random() * 40 + 30
      }));

      if (gift.effect === 'fly') {
         newEffects.length = 0;
