const CommunityView: React.FC = () => {
  // ... (CommunityView logic remains unchanged)
  const [activeTab, setActiveTab] = useState<'rooms' | 'feed' | 'directory'>('rooms');
  const [posts, setPosts] = useState(INITIAL_POSTS);
  const [contacts, setContacts] = useState(INITIAL_CONTACTS);
  const [activeVoiceRoom, setActiveVoiceRoom] = useState<Room | null>(null);
  const [isRoomMinimized, setIsRoomMinimized] = useState(false);
  const [isMicOn, setIsMicOn] = useState(false);
  const [showToastMsg, setShowToastMsg] = useState<string | null>(null);

  // Custom Room State
  const [showCreateRoom, setShowCreateRoom] = useState(false);
  const [myRoom, setMyRoom] = useState<Room | null>(null);

  // Password Prompt State
  const [showPasswordPrompt, setShowPasswordPrompt] = useState(false);
  const [pendingRoom, setPendingRoom] = useState<Room | null>(null);
  const [inputPassword, setInputPassword] = useState("");

  const showToast = (msg: string) => {
    setShowToastMsg(msg);
    setTimeout(() => setShowToastMsg(null), 3000);
  };

  const handleCreateRoom = (name: string, type: RoomType, password?: string) => {
      const config = THEME_CONFIGS[type];
      const newRoom: Room = {
         id: `custom-${Date.now()}`,
         type: type,
         label: name,
         icon: config.icon,
         color: config.color,
         bg: config.bg,
         desc: config.desc,
         action: 'voice',
         participants: 1,
         isCustom: true,
         hostId: 'me',
         password: password
      };
      setMyRoom(newRoom);
      setActiveVoiceRoom(newRoom);
      setIsRoomMinimized(false);
      setShowCreateRoom(false);
      showToast("房间创建成功！");
  };

  const handleShareToFeed = (room: Room, comment: string) => {
    const newPost: CommunityPost = {
        id: `share-${Date.now()}`,
        userId: 'me',
        userName: MOCK_USER.name,
        userAvatar: MOCK_USER.avatar,
        userRole: MOCK_USER.degree,
        content: comment || `邀请大家来【${room.label}】一起交通！`,
        timestamp: '刚刚',
        likes: 0,
        comments: 0,
        likedByMe: false,
        category: 'share',
        connectionStatus: 'none',
        sharedRoom: room
    };
    setPosts([newPost, ...posts]);
    showToast("已分享到校友圈");
  };

  const handleJoinRoom = (room: Room) => {
      // If it's my own room, bypass password
      if (room.isCustom && room.hostId === 'me') {
          setActiveVoiceRoom(room);
          setIsRoomMinimized(false);
          return;
      }

      // If room has password
      if (room.password) {
          setPendingRoom(room);
          setInputPassword("");
          setShowPasswordPrompt(true);
      } else {
          setActiveVoiceRoom(room);
          setIsRoomMinimized(false);
      }
  };

  const handleConfirmPassword = () => {
      if (pendingRoom && inputPassword === pendingRoom.password) {
          setActiveVoiceRoom(pendingRoom);
          setIsRoomMinimized(false);
          setShowPasswordPrompt(false);
          setPendingRoom(null);
          showToast("密码验证成功");
      } else {
          showToast("密码错误，请重试");
      }
  };

  const staticRooms: Room[] = [
    { id: 'prayer_room', type: 'prayer', label: '祷告室', icon: HandHeart, color: 'text-rose-500', bg: 'bg-rose-50', desc: '早晨 6:00 - 7:00 | 每日晨更祷告会', action: 'voice', participants: 12 },
    { id: 'praise_room', type: 'praise', label: '赞美室', icon: Music, color: 'text-amber-500', bg: 'bg-amber-50', desc: '全天开放 | 诗歌敬拜与分享', action: 'voice', participants: 8 },
    { id: 'bible_reading', type: 'bible', label: '读经室', icon: BookOpen, color: 'text-blue-500', bg: 'bg-blue-50', desc: '研读《罗马书》 | 李教授带读', action: 'voice', participants: 25 },
    { id: 'preaching_room', type: 'preaching', label: '讲道室', icon: Mic2, color: 'text-purple-500', bg: 'bg-purple-50', desc: '主日信息分享 | 讲员：张院长', action: 'voice', participants: 45 },
    { id: 'fellowship_room', type: 'fellowship', label: '交通室', icon: Coffee, color: 'text-emerald-500', bg: 'bg-emerald-50', desc: '肢体交通，分享生活点滴与恩典。', action: 'voice' },
  ];

  const displayRooms = myRoom ? [myRoom, ...staticRooms] : staticRooms;

  return (
    <div className="min-h-screen bg-slate-50 pb-24 relative animate-fade-in">
        {showCreateRoom && <CreateRoomModal onClose={() => setShowCreateRoom(false)} onCreate={handleCreateRoom} />}

        {/* Password Prompt Modal */}
        {showPasswordPrompt && (
            <div className="fixed inset-0 z-[60] bg-black/60 backdrop-blur-sm flex items-center justify-center p-6 animate-fade-in">
               <div className="bg-white w-full max-w-xs rounded-3xl p-6 animate-scale-in shadow-2xl relative">
                  <button onClick={() => setShowPasswordPrompt(false)} className="absolute top-4 right-4 text-slate-400 hover:text-slate-600"><X size={20}/></button>
                  <div className="flex flex-col items-center mb-6">
                     <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mb-4 text-slate-400">
                        <Lock size={32} />
                     </div>
                     <h3 className="text-lg font-bold text-slate-900">私密房间</h3>
                     <p className="text-xs text-slate-500 mt-1">请输入密码以加入房间</p>
                  </div>

                  <div className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 flex items-center focus-within:ring-2 focus-within:ring-blue-500 mb-6 transition-all">
                      <KeyRound size={18} className="text-slate-400 mr-2"/>
                      <input 
                         type="password"
                         value={inputPassword}
                         onChange={(e) => setInputPassword(e.target.value)}
                         placeholder="输入房间密码"
                         className="bg-transparent border-none outline-none w-full text-sm font-medium text-slate-900 placeholder:text-slate-400"
                         autoFocus
                      />
                  </div>

                  <button 
                     onClick={handleConfirmPassword}
                     disabled={!inputPassword}
                     className="w-full bg-blue-900 text-white py-3 rounded-xl font-bold shadow-lg hover:bg-blue-800 disabled:opacity-50 disabled:shadow-none transition-all"
                  >
                     确认加入
                  </button>
               </div>
            </div>
