                           <div className="bg-black/30 backdrop-blur-md rounded-2xl border border-white/10 p-4 relative group">
                              <h3 className="text-xs text-slate-300 font-bold mb-2 flex items-center">
                                 <FileText size={12} className="mr-1"/> 讲章提纲 (仅自己可见)
                              </h3>
                              <textarea 
                                value={sermonNotes}
                                onChange={(e) => setSermonNotes(e.target.value)}
                                className="w-full bg-transparent text-sm text-white/90 font-serif leading-relaxed h-32 resize-none outline-none custom-scrollbar"
                                placeholder="在此输入讲章大纲..."
                              />
                              <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                 <Edit2 size={12} className="text-white/50"/>
                              </div>
                           </div>
                       )}

                       {/* Recording & Tools - Displayed at Bottom */}
                       {isHost && (
                           <div className="flex justify-center gap-3">
                               <button 
                                  onClick={toggleRecording}
                                  className={`flex-1 py-3 rounded-xl text-xs font-bold flex items-center justify-center shadow-lg transition-all ${isRecordingSermon ? 'bg-rose-600 text-white animate-pulse' : 'bg-white/10 hover:bg-white/20 text-white border border-white/10'}`}
                               >
                                   {isRecordingSermon ? <StopCircle size={16} className="mr-2"/> : <Mic size={16} className="mr-2"/>}
                                   {isRecordingSermon ? '停止录音 (点击保存)' : '开始录制讲道'}
                               </button>
                               <button 
                                  onClick={() => setShowBibleSelector(true)}
                                  className="flex-1 py-3 rounded-xl bg-blue-600/80 hover:bg-blue-600 text-white text-xs font-bold border border-blue-500/50 flex items-center justify-center shadow-lg"
                               >
                                  <BookOpen size={16} className="mr-2"/> 分享经文
                               </button>
                           </div>
                       )}
                   </div>
                )}

                {/* FEATURE: Praise Room Music Player */}
                {isPraiseRoom && (
                  <div className="mx-2 mb-4 bg-white/10 backdrop-blur-md rounded-xl p-3 flex items-center border border-white/10 shadow-lg cursor-pointer hover:bg-white/15 transition" onClick={() => setShowPlaylist(true)}>
                     <div className="w-12 h-12 bg-amber-500 rounded-lg flex items-center justify-center mr-3 shrink-0 shadow-md">
                        {isPlaying ? <div className="flex space-x-1 items-end h-4"><span className="w-1 h-4 bg-white animate-pulse"></span><span className="w-1 h-3 bg-white animate-pulse delay-75"></span><span className="w-1 h-4 bg-white animate-pulse delay-150"></span></div> : <Music size={24} className="text-white"/>}
                     </div>
                     <div className="flex-1 min-w-0 mr-2">
                        <h3 className="text-sm font-bold text-white truncate">{currentSong.title}</h3>
                        <p className="text-[10px] text-amber-200">{currentSong.artist}</p>
                     </div>
                     <div className="flex items-center space-x-2" onClick={e => e.stopPropagation()}>
                        <button onClick={() => setIsPlaying(!isPlaying)} className="p-2 rounded-full bg-white text-amber-600 hover:scale-105 transition shadow-sm">
                           {isPlaying ? <Pause size={14} fill="currentColor" /> : <Play size={14} fill="currentColor" />}
                        </button>
                     </div>
                  </div>
                )}

                {/* Audience Grid - Compact */}
                <div className="grid grid-cols-5 gap-y-4 gap-x-2 px-1">
                   {participants.filter(p => p.role === 'listener').map(p => (
                      <div key={p.id} className="flex flex-col items-center cursor-pointer" onClick={() => handleUserClick(p)}>
                         <div className="w-9 h-9 rounded-full bg-white/5 p-[1px] mb-1 border border-white/5 relative">
                            <img src={p.avatar} alt={p.name} className={`w-full h-full rounded-full object-cover transition-opacity ${p.isMutedByHost ? 'grayscale opacity-40' : 'opacity-80 hover:opacity-100'}`} />
                            {p.isMutedByHost && (
                                <div className="absolute bottom-0 right-0 bg-rose-500 rounded-full p-0.5 border border-slate-900">
                                    <MicOff size={8} className="text-white"/>
                                </div>
                            )}
                         </div>
                         <span className="text-[9px] text-slate-400 truncate w-full text-center">{p.name}</span>
                      </div>
                   ))}
                </div>
          </div>

          {/* Bottom: Chat Area */}
          <div className="flex-1 min-h-0 relative w-full flex flex-col z-20">
             <div className="absolute top-0 left-0 right-0 h-12 bg-gradient-to-b from-transparent to-transparent pointer-events-none z-10"></div>
             <div 
                ref={chatContainerRef} 
                className="flex-1 overflow-y-auto px-4 pb-2 scrollbar-hide pt-2"
                style={{ maskImage: 'linear-gradient(to bottom, transparent 0%, black 15%)' }}
             >
                <div className="min-h-[30%]"></div>
                <div className="space-y-3 flex flex-col justify-end min-h-full pb-2">
                    <div className="flex justify-center py-2 opacity-70">
                       <span className="text-[10px] text-white/60 bg-black/20 backdrop-blur-sm px-3 py-1 rounded-full border border-white/5">
                          {isHost ? '您是房主，可以随时修改标题与主题' : '聊天室已连接'}
                       </span>
                    </div>
                    {roomChats.map(msg => {
                      const isMe = msg.user === '我';
                      if (msg.type === 'system') return (
                          <div key={msg.id} className="w-full flex justify-center my-1">
                              <div className="bg-white/10 backdrop-blur rounded-full px-3 py-1 text-[10px] text-white/80 font-medium border border-white/5 shadow-sm">{msg.text}</div>
                          </div>
                      );
                      return (
                        <div key={msg.id} className={`flex w-full ${isMe ? 'justify-end' : 'justify-start'} animate-slide-in-up`}>
                           <div className={`flex max-w-[85%] gap-2 ${isMe ? 'flex-row-reverse' : 'flex-row'}`}>
                              <div className="shrink-0 flex flex-col justify-end">
                                <div className="w-8 h-8 rounded-full overflow-hidden border border-white/20 shadow-md bg-black/20">
                                    <img src={msg.userAvatar || `https://ui-avatars.com/api/?name=${msg.user}&background=random`} alt={msg.user} className="w-full h-full object-cover" />
                                </div>
                              </div>
                              <div className={`flex flex-col ${isMe ? 'items-end' : 'items-start'}`}>
                                 {!isMe && <span className="text-[10px] text-white/60 ml-1 mb-0.5">{msg.user}</span>}
                                 {msg.type === 'gift' ? (
                                    <div className="rounded-2xl py-1.5 px-3 bg-gradient-to-r from-amber-600/40 to-orange-600/40 backdrop-blur-md border border-amber-500/30 shadow-sm flex items-center text-xs text-white">
                                       <span className="font-bold mr-1 text-amber-50">{msg.user}</span>
                                       <span className="opacity-80 text-[10px] mr-1">送出了</span>
                                       <span className="font-bold text-amber-200">{msg.giftData?.name}</span>
                                       <span className="text-lg ml-1">{msg.giftData?.icon}</span>
                                    </div>
                                 ) : (
                                    <div className={`px-3.5 py-2 rounded-2xl text-sm backdrop-blur-md shadow-sm border text-white/95 leading-relaxed whitespace-pre-wrap
                                        ${isMe ? 'bg-gradient-to-br from-blue-600/40 to-blue-500/40 border-blue-400/20 rounded-br-none' : (msg.type === 'verse' ? 'bg-emerald-900/40 border-emerald-500/30 rounded-bl-none' : (msg.type === 'hymn' ? 'bg-amber-900/40 border-amber-500/30 rounded-bl-none' : 'bg-white/10 border-white/10 rounded-bl-none'))}
                                    `}>
                                       <span className="drop-shadow-md">{msg.text}</span>
                                    </div>
                                 )}
                              </div>
                           </div>
                        </div>
                      );
                    })}
                </div>
             </div>
          </div>
        </div>

        {/* 4. Bottom Controls */}
        <div className="bg-black/60 backdrop-blur-xl border-t border-white/10 p-3 pb-[calc(env(safe-area-inset-bottom)+12px)] shrink-0 z-50 relative transition-all">
           {showMenu && (
             <div className="absolute bottom-full left-4 mb-2 w-48 bg-slate-800 rounded-xl border border-slate-700 shadow-2xl overflow-hidden animate-scale-in origin-bottom-left z-50">
                {isHost && (
                  <button onClick={() => { setShowMenu(false); setShowThemeSwitcher(true); }} className="w-full text-left px-4 py-3 hover:bg-white/5 flex items-center text-sm text-blue-300 border-b border-white/5">
                     <Palette size={16} className="mr-2"/> 切换主题
                  </button>
                )}
                {isOnStage && (
                    <button onClick={handleLeaveStage} className="w-full text-left px-4 py-3 hover:bg-white/5 flex items-center text-sm text-rose-400 border-b border-white/5">
                       <LogOut size={16} className="mr-2"/> 下麦
                    </button>
                )}
                <button onClick={() => setShowInvite(true)} className="w-full text-left px-4 py-3 hover:bg-white/5 flex items-center text-sm text-white">
                   <UserPlus2 size={16} className="mr-2 text-blue-400"/> 邀请好友
                </button>
             </div>
           )}

           {showGiftPanel && (
             <div className="absolute bottom-full left-0 right-0 mb-0 bg-slate-800 rounded-t-2xl border-t border-slate-700 shadow-2xl animate-slide-up z-50 p-4">
                <div className="flex justify-between items-center mb-4">
                   <h3 className="text-white font-bold text-sm">送出祝福</h3>
                   <button onClick={() => setShowGiftPanel(false)} className="text-slate-400 hover:text-white"><ChevronDown size={20}/></button>
                </div>
                <div className="grid grid-cols-5 gap-2">
                   {GIFT_ITEMS.map(gift => (
                      <button key={gift.id} onClick={() => handleSendGift(gift)} className="flex flex-col items-center p-2 rounded-xl hover:bg-white/10 transition">
                         <div className="text-3xl mb-1 transform hover:scale-110 transition">{gift.icon}</div>
                         <span className="text-[10px] text-white font-medium">{gift.name}</span>
                      </button>
                   ))}
                </div>
             </div>
           )}

           {showResponsePanel && (
             <div className="absolute bottom-full right-2 mb-3 bg-slate-800/95 backdrop-blur-xl rounded-2xl border border-slate-600/50 shadow-2xl animate-scale-in z-[60] p-4 w-64 origin-bottom-right">
                <div className="flex justify-between items-center mb-3">
                   <h3 className="text-xs font-bold text-white/90 flex items-center"><MessageCircle size={14} className="mr-1.5 text-purple-400"/> 快速回应</h3>
                   <button onClick={() => setShowResponsePanel(false)} className="text-slate-400 hover:text-white"><X size={14}/></button>
                </div>
                <div className="grid grid-cols-2 gap-2">
                   {/* Switch Responses based on room type */}
                   {(isPrayerRoom ? PRAYER_RESPONSES : QUICK_RESPONSES).map((item, idx) => (
                      <button key={idx} onClick={() => handleQuickResponse(item)} className="flex items-center justify-start px-3 py-2.5 rounded-xl bg-white/10 hover:bg-white/20 transition active:scale-95 border border-white/5 group">
                         <span className="text-lg mr-2 group-hover:scale-110 transition-transform">{item.icon}</span>
                         <span className="text-xs font-bold text-white">{item.text}</span>
                      </button>
                   ))}
                </div>
             </div>
           )}

           <div className="flex items-center space-x-2">
              <button onClick={() => setShowMenu(!showMenu)} className="shrink-0 w-10 h-10 rounded-full bg-white/10 text-slate-300 border border-white/5 flex items-center justify-center hover:bg-white/20 transition active:scale-95">
                 <Plus size={20} />
              </button>

              <div className="flex-1 bg-white/10 hover:bg-white/15 transition-colors rounded-full px-1 py-1 flex items-center border border-white/5 focus-within:border-white/20 focus-within:bg-white/20 h-10">
                 <input 
                   type="text" 
                   value={chatInput}
                   onChange={(e) => setChatInput(e.target.value)}
                   onKeyDown={(e) => e.key === 'Enter' && handleSendChat()}
                   placeholder={isPreachingRoom || isPrayerRoom ? "点击 '回应' 互动..." : "发送消息..."}
                   className="bg-transparent border-none outline-none text-sm text-white placeholder-white/40 flex-1 min-w-0 px-3" 
                 />
                 {chatInput.trim() ? (
                    <button onClick={handleSendChat} className="w-8 h-8 rounded-full bg-blue-600 text-white flex items-center justify-center hover:bg-blue-700 transition mr-0.5">
                       <Send size={14} />
                    </button>
                 ) : (
                    <div className="w-8 h-8 rounded-full flex items-center justify-center">
                        <MessageCircle size={16} className="text-white/20" />
                    </div>
                 )}
              </div>

              {isOnStage ? (
                 <button onClick={toggleMic} className={`shrink-0 w-10 h-10 rounded-full flex items-center justify-center transition-all shadow-lg ${isMicOn ? 'bg-blue-600 text-white ring-2 ring-white/20' : 'bg-white/10 text-slate-300 hover:bg-white/20 border border-white/5'}`}>
                     {isMicOn ? <Mic size={18} className="animate-pulse"/> : <MicOff size={18} />}
                 </button>
              ) : (
                 <button onClick={handleRaiseHand} className="shrink-0 w-10 h-10 rounded-full flex items-center justify-center transition-all shadow-lg bg-white/10 text-slate-300 border border-white/5 hover:bg-white/20 active:scale-95">
                     <Hand size={18} />
                 </button>
              )}

              <button onClick={() => setShowGiftPanel(!showGiftPanel)} className="shrink-0 w-10 h-10 rounded-full flex items-center justify-center bg-gradient-to-br from-amber-500 to-orange-600 text-white shadow-lg hover:brightness-110 transition active:scale-95">
                 <Gift size={18} />
              </button>

               <button 
                  onClick={() => { 
                      if(isPreachingRoom || isPrayerRoom) { 
                          setShowResponsePanel(!showResponsePanel);
                          setShowGiftPanel(false); // Close others
                          setShowMenu(false);
                      } else { 
                          triggerReaction(); 
                      } 
                  }} 
                  className={`shrink-0 w-10 h-10 rounded-full hover:bg-white/10 transition flex items-center justify-center bg-white/5 border border-white/5 ${isPreachingRoom ? (showResponsePanel ? 'bg-purple-600 text-white border-purple-500' : 'text-purple-400') : (isPrayerRoom ? (showResponsePanel ? 'bg-rose-600 text-white border-rose-500' : 'text-rose-400') : 'text-rose-400')}`}
               >
                   {isPreachingRoom || isPrayerRoom ? (
                       showResponsePanel ? <X size={18} /> : <span className="text-[10px] font-bold">{isPrayerRoom ? '阿们' : '回应'}</span>
                   ) : (
                       <Heart size={18} fill="currentColor"/>
                   )}
               </button>
           </div>
        </div>

        {/* Room Info Modal */}
        {showRoomInfo && (
           <div className="absolute inset-0 z-[70] bg-black/80 backdrop-blur-sm flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowRoomInfo(false)}>
              <div className="bg-white w-full max-w-xs rounded-2xl p-6 relative text-slate-900" onClick={e => e.stopPropagation()}>
                 <div className="flex items-center justify-center mb-4">
                    <div className={`w-16 h-16 rounded-full flex items-center justify-center ${activeVoiceRoom.bg.replace('bg-','bg-opacity-20 ')} ${activeVoiceRoom.color}`}>
                       {activeVoiceRoom.icon && <activeVoiceRoom.icon size={32} />}
                    </div>
                 </div>
                 <h3 className="text-lg font-bold text-center mb-2">{activeVoiceRoom.label}</h3>
                 {activeVoiceRoom.password && <p className="text-xs text-center text-slate-400 mb-2 flex items-center justify-center"><Lock size={12} className="mr-1"/> 私密房间</p>}
                 <div className="bg-slate-50 p-3 rounded-xl border border-slate-100 mb-4">
                    <h4 className="text-xs font-bold text-slate-500 mb-1 uppercase">公告</h4>
                    <p className="text-sm text-slate-700 leading-relaxed">{activeVoiceRoom.announcement || '暂无公告'}</p>
                 </div>

                 {isAiConnected && (
                    <div className="mb-4 flex items-center justify-center text-xs text-emerald-600 bg-emerald-50 p-2 rounded-lg border border-emerald-100">
                       <Wifi size={14} className="mr-1.5"/> 语音牧师在线
                    </div>
                 )}

                 <div className="space-y-2">
                    <button 
                       onClick={() => setShowShareModal(true)}
                       className="w-full py-3 bg-slate-100 text-slate-600 font-bold rounded-xl hover:bg-slate-200 text-sm flex items-center justify-center"
                    >
                       <Share2 size={16} className="mr-2"/> 分享房间
                    </button>

                    {isHost && (
                        <button 
                           onClick={() => { 
                               setPasswordInput(activeVoiceRoom.password || ""); 
                               setShowPasswordSettings(true); 
                               setShowRoomInfo(false); 
                           }}
                           className="w-full py-3 bg-slate-100 text-slate-600 font-bold rounded-xl hover:bg-slate-200 text-sm flex items-center justify-center mb-2"
                        >
                           <KeyRound size={16} className="mr-2"/> 房间密码设置
                        </button>
                    )}

                    <button onClick={() => { disconnectFromGemini(); setActiveVoiceRoom(null); setShowRoomInfo(false);}} className="w-full py-3 bg-rose-50 text-rose-600 font-bold rounded-xl hover:bg-rose-100 text-sm flex items-center justify-center">
                       <PhoneOff size={16} className="mr-2"/> 退出房间
                    </button>
                 </div>
                 <button onClick={() => setShowRoomInfo(false)} className="absolute top-4 right-4 text-slate-400 hover:text-slate-600">
                    <X size={20} />
                 </button>
              </div>
           </div>
        )}
      </div>
    );

    return createPortal(overlayContent, document.body);
};
]]></content>
</change>
